const TEMPLATE = "  \"Improving capabilities of law enforcement to counter climate-related challenges\"\n     -> contenttype=project AND \"law enforcement\" AND (\"climate change\" OR \"environmental crime\")\n  \"Crime prevention approaches, online and off-line, tackling the nexus between addictions and crime\"\n     -> contenttype=project AND \"crime prevention\" AND (\"addiction\" OR \"substance abuse\" OR \"drugs\")\n  \"Online harms detection and investigation tools using a short development cycle model\"\n     -> contenttype=project AND (\"online harms\" OR \"illegal content\" OR \"child sexual abuse\" OR \"cybercrime\")\n  \"Open topic on increasing security of citizens against terrorism, including in public spaces\"\n     -> contenttype=project AND (\"counter-terrorism\" OR \"terrorism\") AND \"public spaces\"\n  \"Accessible and available travel facilitation\"\n     -> contenttype=project AND (\"travel facilitation\" OR \"border crossing\" OR \"passenger flow\")\n  \"Trusted, secure, quality future digital travel credentials\"\n     -> contenttype=project AND (\"digital travel credentials\" OR \"digital identity\") AND (\"border\" OR \"travel\")\n  \"Security challenges of the green transition in urban und peri urban areas\"\n     -> contenttype=project AND (\"urban security\" OR \"critical infrastructure\") AND (\"green transition\" OR \"energy transition\")\n  \"Impact of malicious use of Open-Source Intelligence on critical infrastructure business continuity\"\n     -> contenttype=project AND (\"open-source intelligence\" OR \"OSINT\") AND (\"critical infrastructure\" OR \"business continuity\")\n  \"Development of innovative tools, processes, equipment and technologies through responses to disasters and emergencies for search and rescue in hazardous conditions\"\n     -> contenttype=project AND (\"search and rescue\" OR \"first responders\") AND (\"disaster\" OR \"emergency\")\n  \"Open Topic on advanced protective gear optimized for CBRN-E (Chemical, Biological, Radiological, Nuclear, Explosives) environments and new generation of smart protective equipment for disaster responders\"\n     -> contenttype=project AND (\"CBRN\" OR \"chemical biological radiological\") AND (\"protective equipment\" OR \"first responders\")\n  \"Enhancing preparedness for large-scale cross-border disasters\"\n     -> contenttype=project AND (\"cross-border\" OR \"large-scale\") AND (\"disaster\" OR \"civil protection\")\n  \"Public procurement of innovation for security\"\n     -> contenttype=project AND (\"public procurement\" OR \"pre-commercial procurement\") AND \"security\"";
const GUARDRAILS = "You are authoring search queries for the CORDIS Data-Extraction (DET) API. Each query is sent to CORDIS to retrieve EU-funded research PROJECTS whose topic matches a Horizon Europe call's subject; the funded projects' EuroSciVoc research-field classifications are then aggregated into that call's tags. So a query MUST return projects genuinely ABOUT the subject — not a broad keyword soup and not off-topic noise. A wrong query stamps WRONG research fields on the call, which is worse than no tag.\n\nCORDIS DET query syntax — follow EXACTLY, mirror the worked examples:\n- Always begin with `contenttype=project AND ...`.\n- Phrase-quote EVERY multi-word domain term: \"renewable energy\", \"gene therapy\", \"precision agriculture\".\n- Group synonyms / closely related terms with OR inside parentheses: (\"solid-state battery\" OR \"all-solid-state battery\").\n- AND together 1-3 concept groups so the result set is bounded AND on-topic. Too broad/too few terms -> over the 25000-result cap (the extraction fails) or generic noise; too many ANDs -> empty.\n- Prefer specific domain nouns. NEVER use a bare ambiguous single word as the main filter (\"open\", \"topic\", \"advanced\", \"innovative\", \"system\", \"platform\", \"support\", \"new\") — these pull biomedical/irrelevant noise (a verified failure: the bare phrase 'missing persons' returned oncology/nutrition projects).\n- Query the SUBJECT/DOMAIN, not the administrative wording. Strip boilerplate before deriving terms: 'Open topic on ...', trailing '(RIA)'/'(IA)'/'(CSA)', partnership/programme names in parentheses, 'Made in Europe', call-identifier fragments.\n- Use `frameworkProgramme=HORIZON` only when the subject is recent/HE-specific AND your domain terms are otherwise broad (use sparingly; most queries need only domain terms).\n- The cluster theme is the relevance anchor: when a subject term is ambiguous, bias the synonyms toward this cluster's domain.";

const CHUNK = 20;
function chunk(a, n) { const o = []; for (let i = 0; i < a.length; i += n) o.push(a.slice(i, i + n)); return o; }

const AUTHOR_SCHEMA = {
  type: 'object', additionalProperties: false,
  properties: { queries: { type: 'array', items: {
    type: 'object', additionalProperties: false,
    properties: { idx: { type: 'integer' }, query: { type: 'string' },
                  confidence: { type: 'string', enum: ['high', 'medium', 'low'] }, note: { type: 'string' } },
    required: ['idx', 'query'] } } },
  required: ['queries'],
};
const VERIFY_SCHEMA = {
  type: 'object', additionalProperties: false,
  properties: { queries: { type: 'array', items: {
    type: 'object', additionalProperties: false,
    properties: { idx: { type: 'integer' }, query: { type: 'string' }, ok: { type: 'boolean' }, issue: { type: 'string' } },
    required: ['idx', 'query', 'ok'] } } },
  required: ['queries'],
};

function subjLines(items) { return items.map(it => '[' + it.idx + '] ' + it.subject).join('\n'); }

function authorPrompt(cl, items) {
  return GUARDRAILS + '\n\nHorizon Europe ' + cl.theme + '. Every subject below is a CALL in this cluster — ground your domain terms in this theme.\n\n' +
    'Worked examples (subject -> query) from a reviewed cluster, showing the REQUIRED style:\n' + TEMPLATE + '\n\n' +
    'Write ONE CORDIS DET query for EACH subject below. Copy each idx exactly; never invent, merge, or skip an idx. ' +
    'Return {queries:[{idx, query, confidence, note}]} covering every idx.\n\nSubjects:\n' + subjLines(items);
}

function verifyPrompt(cl, items, authored) {
  const byIdx = {}; ((authored && authored.queries) || []).forEach(q => { byIdx[q.idx] = q.query; });
  const lines = items.map(it => '[' + it.idx + '] SUBJECT: ' + it.subject + '\n      QUERY: ' + (byIdx[it.idx] || '(MISSING)')).join('\n');
  return GUARDRAILS + '\n\nAdversarially REVIEW and FIX these CORDIS DET queries for the "' + cl.theme + '" cluster. ' +
    'For each: will it retrieve EU-funded projects genuinely about the subject, bounded (not over the 25000-result cap, not empty), ' +
    'and syntactically valid (begins contenttype=project, every multi-word term phrase-quoted, synonyms OR-grouped)? ' +
    'FIX: off-topic / over-broad terms, unquoted multi-word phrases, bare single-word filters, over-constrained (too many ANDs) queries, ' +
    'a missing contenttype=project, or a MISSING query. Preserve the subject\'s domain intent and keep the cluster theme as the anchor.\n\n' +
    'Return {queries:[{idx, query, ok, issue}]} for EVERY idx: query = the corrected query (echo verbatim if already good), ' +
    'ok = true iff you left it unchanged and it is good, issue = short note when you changed it.\n\n' + lines;
}

const units = [];
for (const cl of CLUSTERS) for (const ch of chunk(cl.items, CHUNK)) units.push({ cl, items: ch });
const totalSubjects = CLUSTERS.reduce((n, c) => n + c.items.length, 0);
log('Authoring ' + totalSubjects + ' CORDIS queries across ' + CLUSTERS.length + ' clusters in ' + units.length + ' chunks');

const verified = await pipeline(units,
  u => agent(authorPrompt(u.cl, u.items), { label: 'author:' + u.cl.source + '#' + u.items[0].idx, phase: 'Author', schema: AUTHOR_SCHEMA }),
  (authored, u) => agent(verifyPrompt(u.cl, u.items, authored || { queries: [] }), { label: 'verify:' + u.cl.source + '#' + u.items[0].idx, phase: 'Verify', schema: VERIFY_SCHEMA }),
);

const out = {};
for (const cl of CLUSTERS) out[cl.source] = {};
units.forEach((u, i) => {
  const v = verified[i];
  if (!v || !v.queries) return;
  for (const q of v.queries) {
    if (q && Number.isInteger(q.idx) && q.query && q.query.trim()) out[u.cl.source][String(q.idx)] = q.query.trim();
  }
});

const coverage = CLUSTERS.map(cl => {
  const have = Object.keys(out[cl.source]).length;
  const missingIdx = cl.items.filter(it => !(String(it.idx) in out[cl.source])).map(it => it.idx);
  return { source: cl.source, total: cl.items.length, authored: have, missingIdx };
});
log('Coverage: ' + coverage.map(c => c.source + ' ' + c.authored + '/' + c.total).join(', '));

return { byIdx: out, coverage };
